    faq: [
      { q: '침팬지를 반드시 볼 수 있다고 보장되나요?', a: '마할레에서의 목격은 시즌 중에는 매우 신뢰할 만하지만, 결코 보장되지는 않습니다 — 광활한 숲속의 야생동물이기 때문입니다. 트래커들은 대부분의 아침마다 밤새 침팬지들이 머문 둥지로부터 공동체의 위치를 파악하며, 이틀간의 트레킹에서 성공률은 매우 높습니다. 이 때문에 저희는 모든 마할레 일정에 최소 이틀의 트레킹을 포함합니다.' },
      { q: '트레킹은 실제로 얼마나 힘든가요?', a: '날마다 다릅니다. 건기에는 침팬지들이 대개 비탈 아래쪽에 있어 편도 한 시간이 채 걸리지 않을 수 있습니다. 더 높은 곳에 있을 때는 가파르고 습한 2~3시간의 하이킹을 각오하셔야 합니다. 가끔 하이킹을 하는 정도의 적당한 체력이 있다면 누구나 무리 없이 해낼 수 있습니다. 이동에 대한 우려가 있으시면 알려주시면 더 수월한 시기에 맞춰 계획해 드릴 수 있습니다.' },
      { q: '왜 1시간 제한과 마스크 규정이 있나요?', a: '둘 다 침팬지를 보호하기 위한 것입니다. 침팬지는 인간의 호흡기 감염병에 걸릴 수 있으며, 이는 야생 공동체에 치명적일 수 있습니다. 접촉 시간을 제한하는 것은 그들의 행동을 자연스럽게 유지하기 위함입니다. 한 시간은 순식간에 지나가지만, 근거리에서 진정으로 알찬 한 시간입니다.' },
      { q: '아이도 참여할 수 있나요?', a: '마할레의 침팬지 트레킹 최소 연령은 12세입니다. 더 어린 자녀가 있는 가족은 최소 연령 제한이 없는 클래식 게임 드라이브 사파리가 더 적합합니다.' },
      { q: '마할레는 어떻게 가나요?', a: '경비행기로만 갈 수 있습니다 — 육로 접근은 불가능합니다. 정기 전세기가 아루샤에서 출발하며(경유 포함 약 4~5시간), 이후 탕가니카호를 따라 아름다운 보트 이동을 거쳐 캠프에 도착합니다. 항공편은 주중 정해진 요일에만 운행되며, 이것이 일정 길이를 결정짓습니다.' },
      { q: '트레킹 외에 또 무엇을 할 수 있나요?', a: '탕가니카호가 체험의 나머지 절반을 채워줍니다 — 고유종 시클리드 어류 사이에서의 스노클링, 카약, 낚시, 다우 크루즈, 그리고 그저 해변에서 쉬는 것까지. 대부분의 게스트는 오전에 트레킹을 하고 오후에는 물 위나 물속에서 시간을 보냅니다.' },
      { q: '탄자니아에서 침팬지 트레킹 비용은 얼마인가요?', a: '마할레 일정은 3~5일 기준 1인당 약 $4,100부터 시작하며, 왕복 경비행기, 보트 이동, 공원 및 트레킹 요금, 식사, 호숫가 숙박이 포함되어 있습니다. 오지의 항공편 이동 물류가 주된 비용 요인입니다.' },
    ],
    ctaHeading: '마할레의 침팬지를 만날 준비가 되셨나요?',
