          '**그룹 규모** — 이러한 만남은 대규모로 확장할 수 없습니다. 소규모 프라이빗 그룹은 1인당 비용이 다소 높아지지만, \'투어\'가 아닌 \'방문\'처럼 느껴지는 아침을 경험하게 됩니다.',
          '**어느 정도까지 깊이 들어가느냐** — 마을에 잠깐 들르는 것만으로는 비용이 크게 들지 않지만, 하드자베 + 다토가와 현지 통역사가 함께하는 완전한 에야시 몰입 체험은 하루 전체를 할애하는 만큼 그에 맞는 가격이 책정됩니다.',
          '**그 주변을 둘러싼 사파리** — 문화 체험을 둘러싼 야생동물 일정은 공원, 롯지, 계절 등 일반적인 사파리 가격 체계를 따릅니다.',
